#!/usr/bin/env node

/**
 * Bolt Project Detector
 *
 * Detects if a project was generated by Bolt (StackBlitz AI Tool) based on:
 * - StackBlitz configuration files (.stackblitzrc)
 * - package.json stackblitz field
 * - WebContainer-supported frameworks (React, Vue, Angular, etc.)
 * - Directory structure patterns
 * - Build configuration
 *
 * Detection Confidence Levels:
 * - 100% (1.0): .stackblitzrc exists OR stackblitz field in package.json
 * - 85% (0.85): Common Bolt framework patterns detected
 * - 70% (0.70): WebContainer-compatible framework found
 * - Secondary: Directory structure and other patterns
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { FrameworkDetector } from './framework-detector.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const fsPromises = fs.promises;

class BoltDetector {
  constructor(projectRoot = process.cwd()) {
    this.projectRoot = projectRoot;
    this.priority = 2; // High priority
    this.indicators = {
      strong: 0,
      medium: 0,
      weak: 0
    };
    this.findings = [];
    this.metadata = {};
  }

  /**
   * Main detection method
   * @param {string} [projectRoot] - Project root directory (optional, defaults to constructor value)
   */
  async detect(projectRoot = this.projectRoot) {
    this.projectRoot = projectRoot;
    this.indicators = {
      strong: 0,
      medium: 0,
      weak: 0
    };
    this.findings = [];
    this.metadata = {};

    try {
      // Check primary signatures first (100% confidence)
      const primaryDetection = await this.checkPrimarySignatures();
      if (primaryDetection.confidence === 1.0) {
        return {
          tool: 'bolt',
          confidence: 1.0,
          evidence: this.findings,
          metadata: primaryDetection.metadata,
          isConfident: true
        };
      }

      // Check secondary signatures (85% confidence)
      await this.checkSecondarySignatures();
      await this.checkPackageJson();
      await this.checkDirectoryStructure();
      await this.checkBuildConfiguration();

      const confidence = this.calculateConfidence();

      return {
        tool: confidence > 0.8 ? 'bolt' : null,
        confidence,
        evidence: this.findings,
        metadata: this.metadata,
        isConfident: confidence >= 0.85
      };
    } catch (error) {
      return {
        tool: null,
        confidence: 0,
        evidence: this.findings,
        metadata: {},
        error: error.message,
        isConfident: false
      };
    }
  }

  /**
   * Check for primary signatures (100% confidence)
   * - .stackblitzrc file
   * - stackblitz field in package.json
   */
  async checkPrimarySignatures() {
    // Check for .stackblitzrc (100% confidence)
    try {
      const stackblitzrcPath = path.join(this.projectRoot, '.stackblitzrc');
      const content = await fsPromises.readFile(stackblitzrcPath, 'utf-8');
      const config = JSON.parse(content);

      this.indicators.strong += 10;
      this.findings.push({
        type: 'strong',
        confidence: 1.0,
        message: '.stackblitzrc file found (100% Bolt indicator)',
        file: '.stackblitzrc',
        details: {
          hasInstallDependencies: !!config.installDependencies,
          hasStartCommand: !!config.startCommand,
          compileTrigger: config.compileTrigger || 'not specified'
        }
      });

      this.metadata.framework = config.framework || 'unknown';
      this.metadata.buildTool = 'vite';
      this.metadata.container = 'webcontainer';
      this.metadata.stackblitzConfig = config;

      return {
        confidence: 1.0,
        metadata: this.metadata
      };
    } catch (error) {
      // Continue to check package.json
    }

    // Check for stackblitz field in package.json (100% confidence)
    try {
      const packagePath = path.join(this.projectRoot, 'package.json');
      const content = await fsPromises.readFile(packagePath, 'utf-8');
      const pkg = JSON.parse(content);

      if (pkg.stackblitz) {
        this.indicators.strong += 10;
        this.findings.push({
          type: 'strong',
          confidence: 1.0,
          message: 'stackblitz field found in package.json (100% Bolt indicator)',
          file: 'package.json',
          details: {
            hasInstallDependencies: !!pkg.stackblitz.installDependencies,
            hasStartCommand: !!pkg.stackblitz.startCommand,
            compileTrigger: pkg.stackblitz.compileTrigger || 'not specified'
          }
        });

        this.metadata.framework = pkg.stackblitz.framework || 'unknown';
        this.metadata.buildTool = 'vite';
        this.metadata.container = 'webcontainer';

        return {
          confidence: 1.0,
          metadata: this.metadata
        };
      }
    } catch (error) {
      // Continue to secondary detection
    }

    return {
      confidence: 0,
      metadata: this.metadata
    };
  }

  /**
   * Check for secondary signatures (70-85% confidence)
   * - Use FrameworkDetector to identify any WebContainer-compatible framework
   * - Detect build tools (Vite, Angular CLI, etc.)
   * - Check for TypeScript
   */
  async checkSecondarySignatures() {
    try {
      const packagePath = path.join(this.projectRoot, 'package.json');
      const content = await fsPromises.readFile(packagePath, 'utf-8');
      const pkg = JSON.parse(content);

      const deps = { ...pkg.dependencies, ...pkg.devDependencies };

      // Use FrameworkDetector to identify frameworks
      const frameworkDetector = new FrameworkDetector();
      const frameworkResult = await frameworkDetector.detect(this.projectRoot);

      if (frameworkResult.frameworks.length > 0) {
        const primaryFramework = frameworkResult.primary;

        // Detect build tool based on framework and dependencies
        let buildTool = 'npm';
        let startCommand = null;
        let buildCommand = null;

        if (primaryFramework === 'angular') {
          buildTool = 'angular-cli';
          startCommand = 'ng serve';
          buildCommand = 'ng build';
          this.indicators.strong += 6;
          this.findings.push({
            type: 'medium',
            confidence: 0.80,
            message: `Angular project detected (80% Bolt confidence)`,
            file: 'package.json',
            framework: primaryFramework,
            buildTool
          });
        } else if (primaryFramework === 'remix') {
          buildTool = deps['vite'] ? 'vite' : 'remix';
          this.indicators.strong += 7;
          this.findings.push({
            type: 'medium',
            confidence: 0.85,
            message: `Remix project detected (85% Bolt confidence)`,
            file: 'package.json',
            framework: primaryFramework,
            buildTool
          });
        } else if (deps['vite']) {
          // Only claim Vite projects with weak confidence to avoid conflicts with FigmaDetector
          // Figma Make also uses React+Vite+TypeScript stack
          buildTool = 'vite';
          this.indicators.weak += 2;
          this.findings.push({
            type: 'weak',
            message: `${primaryFramework} + Vite project detected (WebContainer compatible)`,
            file: 'package.json',
            framework: primaryFramework,
            buildTool
          });
        } else {
          // Other frameworks (React, Vue, etc.)
          this.indicators.weak += 1;
          this.findings.push({
            type: 'weak',
            message: `${primaryFramework} project detected (WebContainer compatible)`,
            file: 'package.json',
            framework: primaryFramework
          });
        }

        this.metadata.framework = primaryFramework;
        this.metadata.buildTool = buildTool;

        if (startCommand) this.metadata.startCommand = startCommand;
        if (buildCommand) this.metadata.buildCommand = buildCommand;

        // Check for TypeScript
        const hasTypeScript = !!deps['typescript'] ||
                             await this.fileExists(path.join(this.projectRoot, 'tsconfig.json'));
        if (hasTypeScript) {
          this.metadata.language = 'typescript';
        }
      }
    } catch (error) {
      // Package.json not found or invalid
    }
  }

  /**
   * Check package.json for Bolt-related patterns
   */
  async checkPackageJson() {
    try {
      const packagePath = path.join(this.projectRoot, 'package.json');
      const content = await fsPromises.readFile(packagePath, 'utf-8');
      const pkg = JSON.parse(content);

      const deps = { ...pkg.dependencies, ...pkg.devDependencies };

      // Check for AI SDK (used in Bolt)
      if (deps['ai'] || deps['anthropic']) {
        this.indicators.medium += 1;
        this.findings.push({
          type: 'weak',
          message: 'AI SDK dependency detected (Bolt integration marker)',
          file: 'package.json',
          packages: ['ai', 'anthropic'].filter(p => deps[p])
        });
      }

      // Check for common Bolt dependencies
      const commonBoltDeps = {
        '@remix-run/react': 10,
        '@remix-run/node': 10,
        '@vitejs/plugin-react': 8,
        'typescript': 5,
        'zustand': 3,
        'tailwindcss': 3,
        'tsx': 2
      };

      let boltScore = 0;
      const foundDeps = [];

      for (const [dep, points] of Object.entries(commonBoltDeps)) {
        if (deps[dep]) {
          boltScore += points;
          foundDeps.push(dep);
        }
      }

      if (foundDeps.length >= 3) {
        this.indicators.medium += 0.5;
        this.findings.push({
          type: 'weak',
          message: `Common Bolt dependencies detected (${foundDeps.length} packages)`,
          file: 'package.json',
          packages: foundDeps
        });
      }

      // Check scripts for Vite/Remix patterns
      const scripts = pkg.scripts || {};
      const remixScripts = Object.values(scripts).filter(s =>
        typeof s === 'string' && /remix|vite|tsx/.test(s)
      );

      if (remixScripts.length > 0) {
        this.indicators.weak += 0.25;
        this.findings.push({
          type: 'weak',
          message: `Remix/Vite scripts detected in package.json`,
          file: 'package.json',
          count: remixScripts.length
        });
      }
    } catch (error) {
      // Package.json processing error
    }
  }

  /**
   * Check for framework-specific directory structures
   */
  async checkDirectoryStructure() {
    try {
      // Check for Angular-specific structure
      const srcDir = path.join(this.projectRoot, 'src');
      const angularJson = path.join(this.projectRoot, 'angular.json');

      if (await this.fileExists(angularJson)) {
        this.indicators.strong += 3;
        this.findings.push({
          type: 'strong',
          confidence: 0.90,
          message: 'angular.json found (Angular CLI project - 90% Bolt confidence)',
          file: 'angular.json',
          isAngularIndicator: true
        });

        this.metadata.framework = this.metadata.framework || 'angular';
        this.metadata.buildTool = 'angular-cli';
      }

      // Check for Remix-specific structure
      const appDir = path.join(this.projectRoot, 'app');
      const routesDir = path.join(appDir, 'routes');

      if (await this.fileExists(routesDir)) {
        this.indicators.strong += 2;
        this.findings.push({
          type: 'medium',
          confidence: 0.85,
          message: 'app/routes/ directory found (Remix route pattern - 85% Bolt confidence)',
          file: 'app/routes/',
          isRemixIndicator: true
        });

        this.metadata.framework = this.metadata.framework || 'remix';
      } else if (await this.fileExists(appDir)) {
        this.indicators.medium += 0.5;
        this.findings.push({
          type: 'medium',
          message: 'app/ directory found (framework convention)',
          file: 'app/'
        });
      }

      // Check for src/ directory (common in Angular, React, etc.)
      if (await this.fileExists(srcDir)) {
        this.indicators.weak += 0.25;
        this.findings.push({
          type: 'weak',
          message: 'src/ directory found (source code)',
          file: 'src/'
        });
      }

      // Check for public directory
      if (await this.fileExists(path.join(this.projectRoot, 'public'))) {
        this.indicators.weak += 0.25;
        this.findings.push({
          type: 'weak',
          message: 'public/ directory found (static assets)',
          file: 'public/'
        });
      }

      // Check for types directory
      if (await this.fileExists(path.join(this.projectRoot, 'types'))) {
        this.indicators.weak += 0.25;
        this.findings.push({
          type: 'weak',
          message: 'types/ directory found (TypeScript definitions)',
          file: 'types/'
        });
      }
    } catch (error) {
      // Directory structure check error
    }
  }

  /**
   * Check build configuration files
   */
  async checkBuildConfiguration() {
    try {
      // Check for vite.config.ts/js
      const viteConfigFiles = ['vite.config.ts', 'vite.config.js', 'vite.config.mjs'];
      for (const configFile of viteConfigFiles) {
        const configPath = path.join(this.projectRoot, configFile);
        if (await this.fileExists(configPath)) {
          try {
            const content = await fsPromises.readFile(configPath, 'utf-8');

            this.indicators.medium += 0.5;
            this.findings.push({
              type: 'weak',
              message: `${configFile} found (Vite build configuration)`,
              file: configFile
            });

            // Check for port 5173 (default Vite dev server port, common in Bolt)
            if (content.includes('5173') || content.includes('port: 5173')) {
              this.indicators.medium += 1;
              this.findings.push({
                type: 'medium',
                message: 'Port 5173 configured in Vite (typical Bolt pattern)',
                file: configFile,
                confidence: 0.70
              });
            }

            // Check for React plugin
            if (content.includes('@vitejs/plugin-react')) {
              this.indicators.weak += 0.25;
              this.findings.push({
                type: 'weak',
                message: '@vitejs/plugin-react configured',
                file: configFile
              });

              this.metadata.framework = this.metadata.framework || 'react';
            }
          } catch (e) {
            // Error reading config file
          }
        }
      }

      // Check for remix.config.js (strong indicator)
      const remixConfigPath = path.join(this.projectRoot, 'remix.config.js');
      if (await this.fileExists(remixConfigPath)) {
        this.indicators.strong += 3;
        this.findings.push({
          type: 'strong',
          message: 'remix.config.js found (Remix framework)',
          file: 'remix.config.js'
        });

        this.metadata.framework = 'remix';
      }

      // Check for tsconfig.json
      const tsconfigPath = path.join(this.projectRoot, 'tsconfig.json');
      if (await this.fileExists(tsconfigPath)) {
        this.indicators.weak += 0.25;
        this.findings.push({
          type: 'weak',
          message: 'tsconfig.json found (TypeScript configuration)',
          file: 'tsconfig.json'
        });

        this.metadata.language = 'typescript';
      }
    } catch (error) {
      // Build configuration check error
    }
  }

  /**
   * Helper method to check file existence
   */
  async fileExists(filePath) {
    try {
      await fsPromises.access(filePath);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Calculate confidence score (0-1)
   * Normalized scoring where:
   * - 10+ strong indicators = 1.0 (100%)
   * - 7+ strong indicators = 0.85 (85%)
   * - 5+ strong indicators = 0.70 (70%)
   * - 3+ strong indicators = 0.50 (50%)
   */
  calculateConfidence() {
    const total =
      this.indicators.strong * 1 +
      this.indicators.medium * 0.5 +
      this.indicators.weak * 0.1;

    // Map total score to confidence percentage
    if (total >= 10) return 1.0;    // 100%
    if (total >= 7) return 0.85;    // 85%
    if (total >= 5) return 0.70;    // 70%
    if (total >= 3) return 0.50;    // 50%
    if (total >= 1) return 0.30;    // 30%
    return Math.min(total / 10, 1.0);  // 0-30%
  }
}

/**
 * Format and display results
 */
function displayResults(result, projectRoot) {
  console.log('\n╔════════════════════════════════════════════════════════╗');
  console.log('║          BOLT PROJECT DETECTION RESULTS                ║');
  console.log('╚════════════════════════════════════════════════════════╝\n');

  console.log(`Project Root: ${projectRoot}`);
  const status = result.tool === 'bolt' ? `✓ Bolt Project (${(result.confidence * 100).toFixed(1)}% confidence)` : '✗ Not a Bolt Project';
  console.log(`Detection Status: ${status}`);
  console.log(`Confidence Score: ${(result.confidence * 100).toFixed(1)}%\n`);

  if (result.error) {
    console.log(`Error: ${result.error}\n`);
    return;
  }

  if (result.evidence.length === 0) {
    console.log('No Bolt indicators detected.\n');
    return;
  }

  console.log('Detected Indicators:');
  console.log('─────────────────────────────────────────────────────────\n');

  // Group by type
  const byType = {
    strong: [],
    medium: [],
    weak: []
  };

  result.evidence.forEach(indicator => {
    byType[indicator.type].push(indicator);
  });

  // Display strong indicators
  if (byType.strong.length > 0) {
    console.log('STRONG INDICATORS (100% Bolt markers):');
    byType.strong.forEach(ind => {
      const confText = ind.confidence ? ` (${(ind.confidence * 100).toFixed(0)}%)` : '';
      console.log(`  ✓ ${ind.message}${confText}`);
      if (ind.file) console.log(`    File: ${ind.file}`);
      if (ind.details) {
        Object.entries(ind.details).forEach(([key, value]) => {
          console.log(`    ${key}: ${value}`);
        });
      }
    });
    console.log();
  }

  // Display medium indicators
  if (byType.medium.length > 0) {
    console.log('MEDIUM INDICATORS (85% confidence):');
    byType.medium.forEach(ind => {
      const confText = ind.confidence ? ` (${(ind.confidence * 100).toFixed(0)}%)` : '';
      console.log(`  ○ ${ind.message}${confText}`);
      if (ind.file) console.log(`    File: ${ind.file}`);
    });
    console.log();
  }

  // Display weak indicators
  if (byType.weak.length > 0) {
    console.log('WEAK INDICATORS (Supporting evidence):');
    byType.weak.forEach(ind => {
      console.log(`  · ${ind.message}`);
      if (ind.file) console.log(`    File: ${ind.file}`);
    });
    console.log();
  }

  // Metadata
  if (Object.keys(result.metadata).length > 0) {
    console.log('Detected Metadata:');
    console.log('─────────────────────────────────────────────────────────');
    Object.entries(result.metadata).forEach(([key, value]) => {
      if (key !== 'stackblitzConfig') {
        const displayValue = typeof value === 'object' ? JSON.stringify(value, null, 2) : value;
        console.log(`  ${key}: ${displayValue}`);
      }
    });
    console.log();
  }

  // Interpretation
  console.log('Interpretation:');
  console.log('─────────────────────────────────────────────────────────');
  if (result.confidence >= 0.99) {
    console.log('✓ DEFINITIVE: This is a Bolt project (primary signatures found)');
  } else if (result.confidence >= 0.85) {
    console.log('✓ VERY LIKELY: This is a Bolt project');
  } else if (result.confidence >= 0.70) {
    console.log('◆ LIKELY: This appears to be a Bolt project');
  } else if (result.confidence >= 0.50) {
    console.log('◇ POSSIBLE: Some Bolt-related characteristics detected');
  } else {
    console.log('✗ UNLIKELY: Not a Bolt project');
  }
  console.log();
}

/**
 * Main entry point
 */
async function main() {
  const args = process.argv.slice(2);
  const projectRoot = args[0] || '.';

  try {
    // Verify project exists
    await fsPromises.access(projectRoot);
  } catch (error) {
    console.error(`Error: Project root not found: ${projectRoot}`);
    process.exit(1);
  }

  const detector = new BoltDetector(projectRoot);
  const result = await detector.detect();

  displayResults(result, projectRoot);

  // Exit with appropriate code
  process.exit(result.tool === 'bolt' ? 0 : 1);
}

// Run if executed directly
if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch(err => {
    console.error('Fatal error:', err);
    process.exit(1);
  });
}

export default BoltDetector;
